package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var dateRec DateRec
var dateFile *os.File
var scanner *bufio.Scanner

func truncateToDigits(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	var mod int64 = 1
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val >= 0 {
		return val % mod
	}
	return -((-val) % mod)
}

func parseNumeric(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func formatNumeric(val int64, width int) string {
	v := truncateToDigits(val, width)
	return fmt.Sprintf("%0*d", width, v)
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func MainPara() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer dateFile.Close()
	scanner = bufio.NewScanner(dateFile)
	// allow long lines if needed
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	dateFile.Close()
	line := "VALID: " + formatNumeric(WsValid, 2) + " BAD MONTH: " + formatNumeric(WsBadMonth, 2) + " BAD DAY: " + formatNumeric(WsBadDay, 2)
	fmt.Println(line)
}

func ReadPara() {
	if scanner.Scan() {
		recStr := scanner.Text()
		if len(recStr) < 12 {
			recStr = recStr + strings.Repeat(" ", 12-len(recStr))
		} else if len(recStr) > 12 {
			recStr = recStr[:12]
		}
		dtIdRaw := recStr[0:4]
		dtYyyyRaw := recStr[4:8]
		dtMmRaw := recStr[8:10]
		dtDdRaw := recStr[10:12]

		dateRec.DtId = dtIdRaw
		dateRec.DtYyyy = truncateToDigits(parseNumeric(dtYyyyRaw), 4)
		dateRec.DtMm = truncateToDigits(parseNumeric(dtMmRaw), 2)
		dateRec.DtDd = truncateToDigits(parseNumeric(dtDdRaw), 2)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	LeapPara()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncateToDigits(WsBadMonth+1, 2)
		line := dateRec.DtId + " BAD MONTH " + formatNumeric(dateRec.DtMm, 2)
		fmt.Println(line)
	} else {
		DaysPara()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncateToDigits(WsBadDay+1, 2)
			line := dateRec.DtId + " BAD DAY " + formatNumeric(dateRec.DtDd, 2) + " MAX " + formatNumeric(WsMaxDay, 2)
			fmt.Println(line)
		} else {
			WsValid = truncateToDigits(WsValid+1, 2)
			line := dateRec.DtId + " VALID " + formatNumeric(dateRec.DtYyyy, 4) + "-" + formatNumeric(dateRec.DtMm, 2) + "-" + formatNumeric(dateRec.DtDd, 2)
			fmt.Println(line)
		}
	}
	ReadPara()
}

func LeapPara() {
	yr := dateRec.DtYyyy
	q := yr / 4
	r := yr % 4
	WsQ = truncateToDigits(q, 4)
	WsR4 = truncateToDigits(r, 3)

	q = yr / 100
	r = yr % 100
	WsQ = truncateToDigits(q, 4)
	WsR100 = truncateToDigits(r, 3)

	q = yr / 400
	r = yr % 400
	WsQ = truncateToDigits(q, 4)
	WsR400 = truncateToDigits(r, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncateToDigits(29, 2)
		} else {
			WsMaxDay = truncateToDigits(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncateToDigits(30, 2)
	default:
		WsMaxDay = truncateToDigits(31, 2)
	}
}

func main() {
	MainPara()
}
